urity definer set search_path = public, chatplay_private as $$ begin return chatplay_private.is_room_member(split_part(p_object_name, '/', 1)::uuid); exception when others then return false; end; $$; create or replace function chatplay_private.is_voice_object_owner(p_object_name text) returns boolean language sql stable security definer set search_path = public, chatplay_private as $$ select split_part(p_object_name, '/', 2) = auth.uid()::text; $$; create or replace function chatplay_private.can_access_realtime_topic(p_topic text) returns boolean language plpgsql stable security definer set search_path = public, chatplay_private as $$ begin if p_topic ~ '^room:[0-9a-fA-F-]{36}$' then return chatplay_private.is_room_member(substring(p_topic from 6)::uuid); elsif p_topic ~ '^game:[0-9a-fA-F-]{36}$' then return chatplay_private.is_game_participant(substring(p_topic from 6)::uuid); end if; return false; exception when others then return false; end; $$; create or replace function chatplay_private.add_room_creator() returns trigger language plpgsql security definer set search_path = public, chatplay_private as $$ begin insert into public.room_members (room_id, user_id, membership_role) values (new.id, new.created_by, 'owner') on conflict do nothing; return new; end; $$; grant execute on all functions in schema chatplay_private to authenticated;
